SQL示例: INSERT INTO global_state (row_id, story_state, current_location, current_minor_region, current_major_region, prev_scene_time, elapsed_time, cur_time)
VALUES (1, '全局状态', '御苑', '新宿区', '东京都', NULL, '0分', '2026-02-03 09:00');

sourceData.updateNode:
每轮推进时更新 prev_scene_time、elapsed_time 和 cur_time；若地点变动则同步更新三级地点字段。

【更新约束】
所有字段均 NOT NULL，不可写 NULL 或空串。

SQL示例(同日推进): UPDATE global_state SET prev_scene_time = '2026-02-03 09:00', elapsed_time = '3小时', cur_time = '2026-02-03 12:00' WHERE row_id = 1;

SQL示例(含位置变动): UPDATE global_state SET current_location = '新宿车站', current_minor_region = '新宿区', current_major_region = '东京都', prev_scene_time = '2026-02-03 12:00', elapsed_time = '30分', cur_time = '2026-02-03 12:30' WHERE row_id = 1;

已存在的这一行，字段值变化时更新：年龄、外貌、身份、现况、所在地点、基础属性、特有属性、随身财物、亲密状态。

SQL示例(近况变化): UPDATE protagonist_info SET current_condition = '疲劳，左膝擦伤', location_name = '御苑' WHERE row_id = 1;

SQL示例(属性变化): UPDATE protagonist_info SET base_attributes = '健康:58; 力量:60; 敏捷:55; 理智:63; 观察:62; 魅力:56', special_attributes = '摄影:75' WHERE row_id = 1;

SQL示例(随身财物变化): UPDATE protagonist_info SET belongings = '钱包里夹着第一次看电影的票根，口袋里剩两颗橘子糖' WHERE row_id = 1;

技能升级或熟练度变化时更新熟练度和说明字段。

SQL示例(才艺进步): UPDATE skills SET proficiency = '精通', skill_description = '能做复杂菜式和烘焙，朋友聚会可以负责全部餐食。报了三个月厨师培训班。' WHERE skill_name = '家常菜烹饪';

SQL示例(失去技能): UPDATE skills SET proficiency = '完全不会', skill_description = '右手骨折后长期未练习，已无法弹奏。原能弹唱大部分流行歌曲。大学时自学。' WHERE skill_name = '吉他弹唱';

已存在的恋爱对象，任何字段变化时更新本表。

【重点规则】
恋人分手、死亡、失踪等情况只更新在场状态、人际关系等字段，绝不删除本行。

SQL示例(更新关系): UPDATE romance_targets SET relation_state = '主角:暧昧,依赖', intimacy_count = intimacy_count + 1 WHERE name = '洛斯莉';

SQL示例(分手/死亡): UPDATE romance_targets SET relation_state = '主角:分手', presence_status = '离场' WHERE name = '洛斯莉';

sourceData.insertNode:
重要角色发生态度变化、经历新事件或产生值得记录的内心想法时，追加一行。

SQL示例(经历事件): INSERT INTO char_journal (row_id,char_name, event_text, thought_text) VALUES ((SELECT COALESCE(MAX(row_id), 0) + 1 FROM char_journal), '学院长', '学院长在走廊驻足，打量了主角片刻后微微点头离开。', NULL);

SQL示例(态度变化): INSERT INTO char_journal (row_id, char_name, event_text, thought_text) VALUES ((SELECT COALESCE(MAX(row_id), 0) + 1 FROM char_journal), '黑市商人', '黑市商人对主角从纯生意往来转为有意抔摇。', NULL);

SQL示例(内心想法): INSERT INTO char_journal (row_id, char_name, event_text, thought_text) VALUES ((SELECT COALESCE(MAX(row_id), 0) + 1 FROM char_journal), '黑市商人', '她考虑是否该把关于主角的那条情报卖个好价钱。', '这个人身上应该还能再榨出点东西……先不急着报价。');

sourceData.ddl:
CREATE TABLE char_journal ( -- 角色札记表
  row_id INTEGER PRIMARY KEY, -- 行号
  time TEXT NOT NULL, -- 角色姓名
  event_text TEXT NOT NULL, -- 客观事件
  thought_text TEXT -- 内心想法
);

sourceData.updateNode:
已有物品的情感分量、类型、品质或数量变化时更新。可堆叠物品不新建重复行。

SQL示例(消耗使用): UPDATE inventory SET quantity = quantity - 1 WHERE item_name = '他送的橘子糖';

SQL示例(情感升级): UPDATE inventory SET item_type = '定情信物', emotional_weight = '随身携带', quality = '羁绊信物', description = '原本只是随手塞的糖，现在被主角穿绳挂在脖子上。每次紧张都会摸一下。' WHERE item_name = '他送的橘子糖';

sourceData.ddl:
CREATE TABLE check_advice ( -- 检定建议表
  row_id INTEGER PRIMARY KEY CHECK(row_id BETWEEN 1 AND 5), -- 行号，仅允许1-5
  display_text TEXT NOT NULL CHECK(LENGTH(display_text) BETWEEN 12 AND 60), -- 展示文本
  dice_command TEXT NOT NULL CHECK(TRIM(dice_command) <> '') -- 骰子命令
);

CREATE TABLE director_plan ( -- 导演规划表
  row_id INTEGER PRIMARY KEY, -- 行号
  plot TEXT NOT NULL, -- 剧情走向
  outline TEXT, -- 大纲
  instruction TEXT NOT NULL -- AI指导
);

CREATE TABLE flight_big_summary ( -- 大总结
  row_id INTEGER PRIMARY KEY, -- 行号
  summary_text TEXT NOT NULL -- 总结
);

